      final pJ = plaintext.codeUnitAt(j) - 97;
      final cI = ciphertext.codeUnitAt(i) - 97;
      final cJ = ciphertext.codeUnitAt(j) - 97;
      if ((pJ + k) % 26 == cI && (pI + k) % 26 == cJ) {
